<?phpnamespace app\store\controller\plat\weixin\wechat;use app\store\controller\Controller;use app\store\model\Keyword as KeywordModel;use think\facade\View;/** * 关键字回复控制器 */class Keyword extends Controller{	/**     * 首页     */    public function index()    {        $model = new KeywordModel;        $list = $model->getList();        return View::fetch('index', compact('list'));    }	/**     * 添加     */    public function add()    {        if ($this->request->isPost()) {            $model = new KeywordModel;            // 新增记录            if ($model->add($this->postData('data'))) {                return $this->renderSuccess('添加成功', url('plat.weixin.wechat.keyword/index'));            }            $error = $model->getError() ?: '添加失败';            return $this->renderError($error);        }        return redirect(url('plat.weixin.wechat.keyword/index'));     }    /**     * 编辑     */    public function edit(int $id)    {        $model = KeywordModel::get($id);        if ($this->request->isGet()) {            if($model){               return $this->renderSuccess('', '', compact('model'));             }            return $this->renderError('获取失败');        }        // 更新记录        if ($model->edit($this->postData('data'))) {            return $this->renderSuccess('更新成功', url('plat.weixin.wechat.keyword/index'));        }        $error = $model->getError() ?: '更新失败';        return $this->renderError($error);    }    /**     * 删除     */    public function delete()    {        $data = $this->postData();        $model = KeywordModel::get($data['id']);        if (!$model->remove()) {            return $this->renderError('删除失败');        }        return $this->renderSuccess('删除成功');    }	/**     * 状态编辑     */    public function status()    {        $data = $this->postData();        $model = KeywordModel::get($data['id']);        // 更新记录        if ($model->status()) {            return $this->renderSuccess('更新成功', url('plat.weixin.wechat.keyword/index'));        }        $error = $model->getError() ?: '更新失败';        return $this->renderError($error);    }}